-- hosts
CREATE TABLE IF NOT EXISTS hosts (
    id                       UUID DEFAULT gen_random_uuid() PRIMARY KEY NOT NULL,
    name                     VARCHAR(50) UNIQUE NOT NULL,
    address                  VARCHAR(16) UNIQUE NOT NULL,
    port                     INT4 NOT NULL,
    status                   host_status NOT NULL,
    host_user                VARCHAR(32) NOT NULL,
    cloud_hypervisor_version TEXT,
    kernel_version           TEXT,
    total_cpus               INT,
    total_memory_bytes       BIGINT,
    available_memory_bytes   BIGINT,
    load_average             DOUBLE PRECISION,
    disk_total_bytes         BIGINT,
    disk_available_bytes     BIGINT,
    resources_updated_at     TIMESTAMPTZ,
    node_version             TEXT,
    last_deployed_image      TEXT,
    architecture             VARCHAR(16),
    firecracker_version      TEXT,
    reservation_class        TEXT,
    placement_labels         JSONB NOT NULL DEFAULT '{}'::jsonb,
    credential_ref           TEXT,
    -- Why the host's last deploy or upgrade failed. Set together with
    -- INSTALLATION_FAILED and cleared by every other status change.
    installation_error       TEXT
);

CREATE INDEX IF NOT EXISTS idx_hosts_reservation_class ON hosts(reservation_class);
CREATE INDEX IF NOT EXISTS idx_hosts_placement_labels  ON hosts USING GIN (placement_labels);

-- networks
CREATE TABLE IF NOT EXISTS networks (
    id         UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name       VARCHAR(50) UNIQUE NOT NULL,
    subnet     CIDR NOT NULL,
    type       VARCHAR(50),
    gateway    INET,
    dns        INET,
    status     network_status NOT NULL DEFAULT 'ACTIVE',
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    vpc_name   VARCHAR(100)
);

CREATE INDEX IF NOT EXISTS idx_networks_vpc_name ON networks(vpc_name) WHERE vpc_name IS NOT NULL;

CREATE TRIGGER update_networks_modtime
BEFORE UPDATE ON networks
FOR EACH ROW
EXECUTE FUNCTION update_modified_column();

-- storage_pools (attached to hosts through host_storage_pools; allocated_bytes
-- is maintained by the storage accounting triggers at the end of this file)
CREATE TABLE IF NOT EXISTS storage_pools (
    id              UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name            VARCHAR(100) UNIQUE NOT NULL,
    pool_type       storage_pool_type NOT NULL,
    status          storage_pool_status NOT NULL DEFAULT 'INACTIVE',
    config          JSONB NOT NULL DEFAULT '{}'::jsonb,
    capacity_bytes  BIGINT,
    allocated_bytes BIGINT NOT NULL DEFAULT 0,
    created_at      TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT storage_pool_allocation_nonnegative CHECK (allocated_bytes >= 0)
);

CREATE INDEX IF NOT EXISTS idx_storage_pools_type   ON storage_pools(pool_type);
CREATE INDEX IF NOT EXISTS idx_storage_pools_status ON storage_pools(status);

CREATE TRIGGER update_storage_pools_modtime
BEFORE UPDATE ON storage_pools
FOR EACH ROW
EXECUTE FUNCTION update_modified_column();

-- host_storage_pools (many-to-many: hosts ↔ storage_pools)
CREATE TABLE IF NOT EXISTS host_storage_pools (
    host_id         UUID NOT NULL REFERENCES hosts(id) ON DELETE CASCADE,
    storage_pool_id UUID NOT NULL REFERENCES storage_pools(id) ON DELETE CASCADE,
    PRIMARY KEY (host_id, storage_pool_id)
);

CREATE INDEX IF NOT EXISTS idx_host_storage_pools_host ON host_storage_pools(host_id);
CREATE INDEX IF NOT EXISTS idx_host_storage_pools_pool ON host_storage_pools(storage_pool_id);

-- storage_objects
CREATE TABLE IF NOT EXISTS storage_objects (
    id              UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name            VARCHAR(100) NOT NULL,
    storage_pool_id UUID REFERENCES storage_pools(id) NOT NULL,
    object_type     storage_object_type NOT NULL,
    size_bytes      BIGINT NOT NULL,
    config          JSONB NOT NULL DEFAULT '{}'::jsonb,
    parent_id       UUID REFERENCES storage_objects(id),
    created_at      TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- NULL means an externally registered object; an empty array is a legacy
    -- UUID-named object whose exact creating host is unknown.
    managed_host_ids UUID[],
    UNIQUE(storage_pool_id, name),
    CONSTRAINT storage_object_size_nonnegative CHECK (size_bytes >= 0)
);

CREATE INDEX IF NOT EXISTS idx_storage_objects_pool   ON storage_objects(storage_pool_id);
CREATE INDEX IF NOT EXISTS idx_storage_objects_type   ON storage_objects(object_type);
CREATE INDEX IF NOT EXISTS idx_storage_objects_parent ON storage_objects(parent_id);

CREATE TRIGGER update_storage_objects_modtime
BEFORE UPDATE ON storage_objects
FOR EACH ROW
