-- vms (no check ties memory_hotplug_size to memory_size: a memory hotplug grows
-- memory_size while memory_hotplug_size keeps the original additional capacity)
CREATE TABLE IF NOT EXISTS vms (
    id                        UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name                      VARCHAR(50) UNIQUE NOT NULL,
    status                    vm_status NOT NULL,
    host_id                   UUID REFERENCES hosts(id),
    hypervisor                hypervisor NOT NULL,
    config                    JSONB NOT NULL,
    boot_source_id            UUID REFERENCES boot_sources(id),
    description               TEXT,
    boot_vcpus                INTEGER NOT NULL,
    max_vcpus                 INTEGER NOT NULL,
    cpu_topology              JSONB,
    kvm_hyperv                BOOLEAN DEFAULT false,
    memory_size               BIGINT NOT NULL,
    memory_hotplug_size       BIGINT,
    memory_mergeable          BOOLEAN DEFAULT false,
    memory_shared             BOOLEAN DEFAULT false,
    memory_hugepages          BOOLEAN DEFAULT false,
    memory_hugepage_size      BIGINT,
    memory_prefault           BOOLEAN DEFAULT false,
    memory_thp                BOOLEAN DEFAULT true,
    image_ref                 VARCHAR(512),
    boot_mode                 boot_mode NOT NULL DEFAULT 'KERNEL',
    cloud_init_user_data      TEXT,
    cloud_init_meta_data      TEXT,
    cloud_init_network_config TEXT,
    tags                      TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    created_at                TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at                TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT check_boot_vcpus_max      CHECK (boot_vcpus <= max_vcpus),
    CONSTRAINT check_boot_vcpus_positive CHECK (boot_vcpus > 0),
    CONSTRAINT check_memory_size_positive CHECK (memory_size > 0)
);

CREATE INDEX IF NOT EXISTS idx_vms_hypervisor   ON vms(hypervisor);
