CREATE TABLE IF NOT EXISTS ip_allocations (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    network_id   UUID NOT NULL REFERENCES networks(id) ON DELETE CASCADE,
    ip_address   INET NOT NULL,
    vm_id        UUID REFERENCES vms(id) ON DELETE CASCADE,
    allocated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (network_id, ip_address)
);

-- security_groups
CREATE TABLE IF NOT EXISTS security_groups (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name        VARCHAR(100) UNIQUE NOT NULL,
    description TEXT,
    created_at  TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TRIGGER update_security_groups_modtime
BEFORE UPDATE ON security_groups
FOR EACH ROW
EXECUTE FUNCTION update_modified_column();

-- security_group_rules
CREATE TABLE IF NOT EXISTS security_group_rules (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    security_group_id UUID NOT NULL REFERENCES security_groups(id) ON DELETE CASCADE,
    direction         security_group_direction NOT NULL,
    protocol          security_group_protocol NOT NULL DEFAULT 'ANY',
    cidr              CIDR,
    port_start        INTEGER,
    port_end          INTEGER,
    description       TEXT,
    created_at        TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT check_security_group_rule_ports_positive CHECK (
        port_start IS NULL OR (port_start > 0 AND port_start <= 65535)
    ),
    CONSTRAINT check_security_group_rule_port_range CHECK (
        port_end IS NULL OR (port_end > 0 AND port_end <= 65535 AND port_end >= COALESCE(port_start, port_end))
    ),
    CONSTRAINT check_security_group_rule_ports_pair CHECK (
        (port_start IS NULL AND port_end IS NULL) OR (port_start IS NOT NULL AND port_end IS NOT NULL)
    ),
    CONSTRAINT check_security_group_rule_protocol_ports CHECK (
        protocol IN ('TCP', 'UDP') OR (port_start IS NULL AND port_end IS NULL)
    )
);

CREATE INDEX IF NOT EXISTS idx_security_group_rules_group ON security_group_rules(security_group_id);

-- vm_security_groups (many-to-many: vms ↔ security_groups)
CREATE TABLE IF NOT EXISTS vm_security_groups (
    vm_id             UUID NOT NULL REFERENCES vms(id) ON DELETE CASCADE,
    security_group_id UUID NOT NULL REFERENCES security_groups(id) ON DELETE CASCADE,
    PRIMARY KEY (vm_id, security_group_id)
);

CREATE INDEX IF NOT EXISTS idx_vm_security_groups_vm    ON vm_security_groups(vm_id);
CREATE INDEX IF NOT EXISTS idx_vm_security_groups_group ON vm_security_groups(security_group_id);

-- host_gpus
CREATE TABLE IF NOT EXISTS host_gpus (
    id            UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    host_id       UUID NOT NULL REFERENCES hosts(id) ON DELETE CASCADE,
    pci_address   VARCHAR(20) NOT NULL,
    model         VARCHAR(255),
    vendor        VARCHAR(100),
    vram_bytes    BIGINT,
    iommu_group   INTEGER NOT NULL,
    vm_id         UUID REFERENCES vms(id) ON DELETE SET NULL,
    numa_node     INTEGER NOT NULL DEFAULT -1,
    discovered_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at    TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(host_id, pci_address)
);

CREATE INDEX IF NOT EXISTS idx_host_gpus_host      ON host_gpus(host_id);
CREATE INDEX IF NOT EXISTS idx_host_gpus_available ON host_gpus(host_id) WHERE vm_id IS NULL;
CREATE INDEX IF NOT EXISTS idx_host_gpus_vm        ON host_gpus(vm_id) WHERE vm_id IS NOT NULL;

-- lifecycle_hooks
CREATE TABLE IF NOT EXISTS lifecycle_hooks (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name        TEXT NOT NULL,
    url         TEXT NOT NULL,
    secret      TEXT,
    scope       hook_scope NOT NULL DEFAULT 'GLOBAL',
    scope_value TEXT,
    events      TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT lifecycle_hooks_name_key UNIQUE (name)
);

CREATE INDEX IF NOT EXISTS idx_lifecycle_hooks_scope
    ON lifecycle_hooks (scope, scope_value)
    WHERE active = TRUE;

-- hook_executions
CREATE TABLE IF NOT EXISTS hook_executions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    hook_id         UUID NOT NULL REFERENCES lifecycle_hooks(id) ON DELETE CASCADE,
    vm_id           UUID NOT NULL,
    previous_status TEXT NOT NULL,
    new_status      TEXT NOT NULL,
    status          hook_execution_status NOT NULL DEFAULT 'PENDING',
    attempt_count   INT NOT NULL DEFAULT 0,
    max_attempts    INT NOT NULL DEFAULT 5,
    next_retry_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    payload         JSONB NOT NULL,
    response_status INT,
    response_body   TEXT,
    last_error      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    delivered_at    TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_hook_executions_pending
    ON hook_executions (next_retry_at)
    WHERE status = 'PENDING';

-- sandboxes
CREATE TABLE IF NOT EXISTS sandboxes (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vm_id            UUID NOT NULL UNIQUE REFERENCES vms(id) ON DELETE CASCADE,
    vm_template_id   UUID REFERENCES vm_templates(id) ON DELETE SET NULL,
    name             TEXT NOT NULL UNIQUE,
    status           sandbox_status NOT NULL DEFAULT 'PROVISIONING',
    idle_timeout_secs INT NOT NULL DEFAULT 300,
    last_activity_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    error_message    TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sandboxes_status        ON sandboxes (status);
CREATE INDEX IF NOT EXISTS idx_sandboxes_last_activity ON sandboxes (last_activity_at) WHERE status = 'READY';

-- sandbox_pools
CREATE TABLE IF NOT EXISTS sandbox_pools (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vm_template_id UUID NOT NULL UNIQUE REFERENCES vm_templates(id),
    min_ready      INT NOT NULL DEFAULT 0 CHECK (min_ready >= 0),
    created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- sandbox_pool_members
CREATE TABLE IF NOT EXISTS sandbox_pool_members (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sandbox_pool_id UUID NOT NULL REFERENCES sandbox_pools(id) ON DELETE CASCADE,
    vm_id           UUID NOT NULL UNIQUE REFERENCES vms(id) ON DELETE CASCADE,
    status          sandbox_pool_member_status NOT NULL DEFAULT 'PROVISIONING',
    error_message   TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sandbox_pool_members_pool_status
    ON sandbox_pool_members (sandbox_pool_id, status);

-- host_numa_nodes
CREATE TABLE IF NOT EXISTS host_numa_nodes (
    id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    host_id      UUID NOT NULL REFERENCES hosts(id) ON DELETE CASCADE,
    node_id      INTEGER NOT NULL,
    cpu_list     TEXT NOT NULL DEFAULT '',
    memory_bytes BIGINT,
    distances    INTEGER[] NOT NULL DEFAULT '{}',
    updated_at   TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (host_id, node_id)
);

CREATE INDEX IF NOT EXISTS idx_host_numa_nodes_host ON host_numa_nodes (host_id);

-- audit_logs (every mutating API operation; action and resource_type are TEXT
-- for flexibility)
CREATE TABLE IF NOT EXISTS audit_logs (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    action        TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    resource_id   UUID NOT NULL,
    resource_name TEXT,
    metadata      JSONB,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_audit_logs_resource   ON audit_logs (resource_type, resource_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created_at ON audit_logs (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_action     ON audit_logs (action);

-- ============================================================
-- STORAGE POOL ACCOUNTING
-- ============================================================

-- storage_pools.allocated_bytes follows the size_bytes of the pool's objects,
-- plus deleted objects still queued in storage_cleanup. Capacity is only
-- checked when an allocation grows, so a pool already over capacity can still
-- release space.
CREATE FUNCTION adjust_storage_pool_allocation(pool_id UUID, delta BIGINT)
RETURNS VOID LANGUAGE plpgsql AS $$
BEGIN
    -- Lock the pool row: concurrent reservations cannot spend the same space.
    UPDATE storage_pools
    SET allocated_bytes = allocated_bytes + delta
    WHERE id = pool_id
      AND (delta <= 0 OR capacity_bytes IS NULL OR allocated_bytes + delta <= capacity_bytes);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient storage pool capacity'
            USING ERRCODE = '23514', CONSTRAINT = 'storage_pool_capacity';
    END IF;
END;
$$;

CREATE FUNCTION account_storage_object() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        PERFORM adjust_storage_pool_allocation(NEW.storage_pool_id, NEW.size_bytes);
    ELSIF TG_OP = 'DELETE' THEN
        PERFORM adjust_storage_pool_allocation(OLD.storage_pool_id, -GREATEST(OLD.size_bytes, 0));
    ELSIF NEW.storage_pool_id = OLD.storage_pool_id THEN
        PERFORM adjust_storage_pool_allocation(NEW.storage_pool_id, NEW.size_bytes - GREATEST(OLD.size_bytes, 0));
    ELSE
        -- Consistent lock order also makes moves between pools safe.
        PERFORM id FROM storage_pools
        WHERE id IN (OLD.storage_pool_id, NEW.storage_pool_id) ORDER BY id FOR UPDATE;
        PERFORM adjust_storage_pool_allocation(OLD.storage_pool_id, -GREATEST(OLD.size_bytes, 0));
        PERFORM adjust_storage_pool_allocation(NEW.storage_pool_id, NEW.size_bytes);
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER account_storage_object
AFTER INSERT OR UPDATE OF size_bytes, storage_pool_id OR DELETE ON storage_objects
FOR EACH ROW EXECUTE FUNCTION account_storage_object();

-- Retain the allocation after logical deletion until every owned file has
-- been removed. This trigger and account_storage_object run within the same
-- transaction, including all VM foreign-key checks.
CREATE FUNCTION queue_storage_cleanup() RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE targets UUID[];
BEGIN
    IF OLD.managed_host_ids IS NOT NULL THEN
        targets := OLD.managed_host_ids;
        IF cardinality(targets) = 0 THEN
            SELECT ARRAY(SELECT host_id FROM host_storage_pools
                         WHERE storage_pool_id = OLD.storage_pool_id) INTO targets;
        END IF;
        INSERT INTO storage_cleanup(object_id, pool_id, upper_layer, size_bytes, host_ids)
        VALUES (OLD.id, OLD.storage_pool_id, OLD.object_type = 'OVERLAYBD_UPPER',
                GREATEST(OLD.size_bytes, 0), targets);
        -- account_storage_object has already released this allocation. Avoid
        -- re-applying the growth check to legacy pools already over capacity.
        UPDATE storage_pools SET allocated_bytes = allocated_bytes + GREATEST(OLD.size_bytes, 0)
        WHERE id = OLD.storage_pool_id;
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER queue_storage_cleanup AFTER DELETE ON storage_objects
FOR EACH ROW EXECUTE FUNCTION queue_storage_cleanup();

CREATE FUNCTION release_storage_cleanup() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    PERFORM adjust_storage_pool_allocation(OLD.pool_id, -OLD.size_bytes);
    RETURN NULL;
END;
$$;

CREATE TRIGGER release_storage_cleanup AFTER DELETE ON storage_cleanup
FOR EACH ROW EXECUTE FUNCTION release_storage_cleanup();
